style.css:
@-moz-document domain("chatgpt.com") {
body {
        background-color: #0a0a0a !important;
        color: #ff00ff !important;
        font-family: 'Rubik', sans-serif !important;
    }

    h1, h2, h3, h4, h5, h6, p, a, span {
        text-shadow: 0 0 5px #ff00ff, 0 0 10px #ff00ff, 0 0 20px #ff00ff !important;
    }

    button, .button-container, .encart, input, textarea {
        background-color: transparent !important;
        color: #ff00ff !important;
        font-size: 18px !important;
        border: none !important; /* Suppression complète des bordures */
        padding: 10px 20px !important;
        border-radius: 5px !important;
        box-shadow: none !important; /* Supprime tout effet de glow autour */
        transition: 0.3s ease-in-out !important;
    }

    button svg, .button-container svg, .encart svg, 
    i, .icon, .fa, input::placeholder, .search-icon, 
    .button-icon, .dropdown-arrow {
        filter: drop-shadow(0 0 5px #ff00ff) drop-shadow(0 0 10px #ff00ff) !important;
        fill: #ff00ff !important; /* Couleur rose néon */
        color: #ff00ff !important;
    }

    body::after {
        content: "" !important;
        position: fixed !important;
        top: 50% !important;
        left: 50% !important;
        width: 150vw !important;
        height: 150vh !important;
        background: radial-gradient(circle, rgba(255,0,255,0.1) 0%, rgba(0,0,0,0.8) 100%) !important;
        transform: translate(-50%, -50%) !important;
        z-index: -1 !important;
    }
}
